head.script:
scwin.screenId = "jldfil11040";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_isDisclsConsultServiced", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("isDisclsConsultServiced")))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.getAttachFileList();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil11040.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// as-is 흐름 보존 — 스켈레톤이 대체한 함수가 쓰던 전역 선언
scwin.result = undefined; scwin.attachedNum = undefined;

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil11040.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.attachFileList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.attachFileList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try { if (columnId === 'attachFileNm') { const d = $c.util.getComponent('dlt_attachFileList'); if (!d) { return; } if (typeof scwin.fileDown === 'function') { await scwin.fileDown(String(d.getCellData(rowIndex, "disclsConsultApplId")), String(d.getCellData(rowIndex, "seq"))); } else { console.error('[sdd] 행 동작 미정의: scwin.fileDown (열 attachFileNm)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.fileDown'); } return; } 
    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil11040.attachFileList_oncellclick' }); }
};

/**
 * @event
 * @name scwin.disclsConsultForm_onsubmit
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.disclsConsultForm_onsubmit = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin disclsConsultForm_onsubmit — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        return false
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil11040.disclsConsultForm_onsubmit' }); }
};

/**
 * @event
 * @name scwin.btn_list_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_list_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_list_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.list()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil11040.btn_list_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_list
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_list = async function () {
    const sbmOptions = {
        id: "tx_fn_list",
        method: "post",
        action: "/status/disclsConsult.do",
        ref: "dma_listReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil11040.tx_fn_list" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_fileDown
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_fileDown = async function () {
    try { return await $c.data.downFile("/status/disclsConsult.do", "", ($c.util.getComponent("dma_fileDownReq") ? $c.util.getComponent("dma_fileDownReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name scwin.tx_fn_getAttachFileList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_getAttachFileList = async function () {
    const sbmOptions = {
        id: "tx_fn_getAttachFileList",
        method: "post",
        action: "/status/disclsConsult.do",
        ref: "dma_getAttachFileListReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil11040.tx_fn_getAttachFileList" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_getOtherData
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_getOtherData = async function () {
    const sbmOptions = {
        id: "tx_fn_getOtherData",
        method: "post",
        action: "/status/disclsConsult.do",
        ref: "dma_getOtherDataReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil11040.tx_fn_getOtherData" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.attachFileList_fmt_attachFileNm
 * @author Inswave
 * @date 2026. 09. 29
 * @param data formattedData rowIndex columnIndex
 * @returns
 * @hidden N
*/
scwin.attachFileList_fmt_attachFileNm = function (data, formattedData, rowIndex, columnIndex) { return '<a href="javascript:void(0)"><strong>' + String(data) + '</strong></a>'; };

/**
 * @method
 * @name scwin.list
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.list = async function () {
    /* sdd-asis-lifecycle:begin fn_list — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $("input[name='method']").val("disclsConsultApplList");
    $("form[name='disclsConsultForm']").attr("action", "disclsConsult.do");
    $("form[name='disclsConsultForm']").attr("onsubmit", "");
    { const nr = await scwin.tx_fn_list(); if (nr && nr.responseJSON && nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil11000/jldfil11000.xml", { "method": "disclsConsultApplList" }); } };
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fileDown
 * @author Inswave
 * @date 2026. 09. 29
 * @param ipt_disclsConsultApplId seq
 * @returns
 * @hidden N
*/
scwin.fileDown = async function (ipt_disclsConsultApplId, seq) {
    /* sdd-asis-lifecycle:begin fn_fileDown — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const isDisclsConsultServiced = $c.util.getComponent('ipt_isDisclsConsultServiced').getValue();
    if (isDisclsConsultServiced === 'Y') {
        const oData = await scwin.getOtherData();
        if (oData === '' || oData == null || oData === 'undefined') {
            void('apiKey 조회에 실패');
            return;
        }
        const arr = oData.split('||');
        const apiUrl = scwin.urlInfo();
        $c.util.getComponent('hideFrame').src = apiUrl + '/auth/s1/disclosure/consult-apply/file-download/' + ipt_disclsConsultApplId + '/' + seq + '?apiKey=' + arr[0] + '&integUsrId=' + arr[1];
    } else {
        (document.fileDownForm || { elements: [] }).target = "hideFrame";
        $c.util.getComponent('dma_listReq').set('method', 'disclsConsultFileDown');
        $c.util.getComponent('dma_listReq').set('disclsConsultApplId', ipt_disclsConsultApplId);
        $c.util.getComponent('dma_listReq').set('seq', seq);
        $c.util.getComponent('dma_listReq').set('apiKey', '');
        $c.util.getComponent('dma_listReq').set('integUsrId', '');
        (document.fileDownForm || { elements: [] }).action = 'disclsConsult.do';
        await scwin.tx_fn_fileDown();
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.urlInfo
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.urlInfo = function () {
    /* sdd-asis-lifecycle:begin fn_urlInfo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let returnUrl = '';
    const url = location.host;
    if (url === ('localhost:8081') || url === ('idev-filing.krx.co.kr')) {
        returnUrl = 'https://idev-kind-api.krx.co.kr';
    } else {
        if (url === ('dev-filing.krx.co.kr')) {
            returnUrl = 'https://dev-kind-api.krx.co.kr';
        } else {
            if (url === ('test-filing.krx.co.kr')) {
                returnUrl = 'https://test-kind-api.krx.co.kr';
            } else {
                if (url === ('filing.krx.co.kr')) {
                    returnUrl = 'https://kind-api.krx.co.kr';
                } else {
                    if (url === ('dr-filing.krx.co.kr')) {
                        returnUrl = 'https://dr-kind-api.krx.co.kr';
                    }
                }
            }
        }
    }
    return returnUrl;
    /* sdd-asis-lifecycle:end */
};


// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)
/**
 * @method
 * @name scwin.getAttachFileListDone
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.getAttachFileListDone = function (data) {
    /* sdd-asis-lifecycle:begin fn_getAttachFileList_done — as-is 원문 본문(전환 이관 · 포팅 적용됨) */scwin.result = (typeof data === "string" ? JSON.parse(data) : data); $c.util.getComponent('dlt_attachFileList').setJSON(scwin.result);
    if (scwin.result.length > 0) {
        /* 컨테이너 비움 → setJSON 전체 교체가 대신(D14-A) */
        scwin.attachedNum = scwin.result.length;
        const dCnt = 1;
        /* 컨테이너 조립 루프 → 그리드 공급으로 대체(D14-A): 행은 dlt_attachFileList 가 싣고 열 동작은 그리드 라우터가 낸다 */
        $c.util.getComponent('attachFileList').setStyle("display", "");
    }
    /* sdd-asis-lifecycle:end */
};

/**
 * @method
 * @name scwin.getAttachFileList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.getAttachFileList = async function () {
    const r = await scwin.tx_fn_getAttachFileList();
    try {
        scwin.getAttachFileListDone.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body != null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldfil11040.fn_getAttachFileList' });
    }
    return r;
};

/**
 * @method
 * @name scwin.getOtherDataDone
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.getOtherDataDone = function (data) {
    /* sdd-asis-lifecycle:begin fn_getOtherData_done — as-is 원문 본문(전환 이관 · 포팅 적용됨) */scwin.result = (typeof data === "string" ? JSON.parse(data) : data);
    otherData = scwin.result.apiKey + '||' + scwin.result.integUsrId;
    /* sdd-asis-lifecycle:end */
};

/**
 * @method
 * @name scwin.getOtherData
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.getOtherData = async function () {
    const r = await scwin.tx_fn_getOtherData();
    try {
        scwin.getOtherDataDone.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body != null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldfil11040.fn_getOtherData' });
    }
    return r;
};
